package com.beeboee.magnot.network;
import com.beeboee.magnot.Magnot;import com.beeboee.magnot.client.ClientFerrousRegionStore;import com.beeboee.magnot.region.*;import com.beeboee.magnot.server.FerrousRegionActions;import net.minecraft.core.BlockPos;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.*;import net.minecraftforge.network.*;import net.minecraftforge.network.simple.SimpleChannel;import java.util.*;import java.util.function.Supplier;
public final class MagnotNetwork{private static final String VERSION="2";private static final SimpleChannel CHANNEL=NetworkRegistry.newSimpleChannel(new ResourceLocation(Magnot.MOD_ID,"main"),()->VERSION,VERSION::equals,VERSION::equals);private static int id;private MagnotNetwork(){}public static void register(){CHANNEL.registerMessage(id++,Sync.class,Sync::encode,Sync::decode,Sync::handle,Optional.of(NetworkDirection.PLAY_TO_CLIENT));CHANNEL.registerMessage(id++,Remove.class,Remove::encode,Remove::decode,Remove::handle,Optional.of(NetworkDirection.PLAY_TO_SERVER));}public static void sync(ServerPlayer p){if(p.level instanceof ServerLevel l)CHANNEL.send(PacketDistributor.PLAYER.with(()->p),new Sync(FerrousRegionSavedData.get(l).regions()));}public static void syncDimension(ServerLevel l){CHANNEL.send(PacketDistributor.DIMENSION.with(l::dimension),new Sync(FerrousRegionSavedData.get(l).regions()));}public static void remove(UUID value){CHANNEL.sendToServer(new Remove(value));}public record Sync(List<FerrousRegion> regions){static void encode(Sync p,FriendlyByteBuf b){b.writeVarInt(p.regions.size());for(FerrousRegion r:p.regions){b.writeUUID(r.id());b.writeUUID(r.groupId());b.writeBlockPos(r.min());b.writeBlockPos(r.max());}}static Sync decode(FriendlyByteBuf b){int n=b.readVarInt();List<FerrousRegion> rs=new ArrayList<>(n);for(int i=0;i<n;i++)rs.add(new FerrousRegion(b.readUUID(),b.readUUID(),b.readBlockPos(),b.readBlockPos()));return new Sync(rs);}static void handle(Sync p,Supplier<NetworkEvent.Context> c){c.get().enqueueWork(()->ClientFerrousRegionStore.set(p.regions));c.get().setPacketHandled(true);}}public record Remove(UUID region){static void encode(Remove p,FriendlyByteBuf b){b.writeUUID(p.region);}static Remove decode(FriendlyByteBuf b){return new Remove(b.readUUID());}static void handle(Remove p,Supplier<NetworkEvent.Context> c){ServerPlayer player=c.get().getSender();if(player!=null)c.get().enqueueWork(()->FerrousRegionActions.remove(player,p.region));c.get().setPacketHandled(true);}}}
